import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.2.0/src/p5.flex.mjs"
import { RenderFrag, RDFrag, vert } from "./shader.js"
import { PARAMS, onDrage, Pause, Restart } from "./panel.js"
mountFlex(p5)
new p5((p) => {
	const [WIDTH, HEIGHT] = [p.windowWidth, p.windowHeight]
	const PIXEL_DENSITY = 1
	const CANVAS_SIZE = [WIDTH, HEIGHT]
	const TEXEL_SIZE = [1 / (WIDTH * PIXEL_DENSITY), 1 / (HEIGHT * PIXEL_DENSITY)]
	let prev, next
	let RDShader, RenderShader
// Variables pour l'export
let startTime
let blackPixels = []
let exported = false
let goTransformation = false

Pause.on("change", (e) => (e.value ? p.noLoop() : p.loop()))
Restart.on("change", (e) => (p.loop()))

p.setup = () => {
	p.createCanvas(WIDTH, HEIGHT, p.WEBGL)
	p.flex({ canvas: { fit: p.COVER } })
	p.containerBgColor(51)
	p.parentBgColor(51)
	p.pixelDensity(PIXEL_DENSITY)
	prev = p.createFramebuffer({ format: p.FLOAT, textureFiltering: p.NEAREST })
	next = p.createFramebuffer({ format: p.FLOAT, textureFiltering: p.NEAREST })
	RDShader = p.createShader(vert, RDFrag)
	RenderShader = p.createShader(vert, RenderFrag)
	p.noStroke()
	p.imageMode(p.CENTER)

	// Démarrer le timer
	startTime = p.millis()

	p.describe(`"Reaction-Diffusion" by Zaron Chen, for Iterations  #WCCChallenge`)
}


	p.draw = () => {
	// Vérifier si Restart est demandé
	if (PARAMS.Restart) {
		PARAMS.Restart = false
		exported = false
		blackPixels = []
		startTime = p.millis()
		PARAMS.Clear = true
		p.loop()
	}

	// Vérifier si Transformation est demandée
	if (PARAMS.Transformation) {
		PARAMS.Transformation = false
		if (!exported) {
			console.log("Extraction en cours...")
			extractBlackPixels()
			exported = true
			drawBlackPixel()
			exportSVG() 
		}
	}

	if (!exported) {
		RD()
		render()
	}
}

	const exportSVG = () => {
	if (blackPixels.length === 0) {
		console.log("Aucun pixel à exporter")
		return
	}

	let scale = 1 / (PARAMS.Precision || 1)
	let svgWidth = WIDTH * scale
	let svgHeight = HEIGHT * scale

	let svg = `<?xml version="1.0" encoding="UTF-8"?>
<svg width="${svgWidth}" height="${svgHeight}" xmlns="http://www.w3.org/2000/svg">
<rect width="100%" height="100%" fill="white"/>
<g fill="black">\n`

	for (let i = 0; i < blackPixels.length; i++) {
		let x = blackPixels[i].x + svgWidth / 2
		let y = svgHeight / 2 - blackPixels[i].y

		svg += `  <rect x="${x}" y="${y}" width="${scale}" height="${scale}"/>\n`
	}

	svg += `</g>
</svg>`

	let blob = new Blob([svg], { type: 'image/svg+xml' })
	let url = URL.createObjectURL(blob)
	let link = document.createElement('a')
	link.href = url
	link.download = `reaction-diffusion-${p.millis()}.svg`
	link.click()
	URL.revokeObjectURL(url)

	console.log(`SVG exporté avec ${blackPixels.length} pixels (${svgWidth}x${svgHeight})`)
}




function drawBlackPixel(){
	var scale = 1 / (PARAMS.Precision || 1)

	p.resetShader()
	p.background(0)
	p.fill(255, 0, 0, 200)
	for (let i = 0; i < blackPixels.length; i++) {
		p.rect(blackPixels[i].x, blackPixels[i].y, scale)
	}
}


const RD = () => {
	for (let i = 0; i < PARAMS.Iterations; i++) {
		;[prev, next] = [next, prev]
		next.begin()
		p.shader(RDShader)
		RDShader.setUniform("tex0", prev)
		RDShader.setUniform("canvasSize", CANVAS_SIZE)
		RDShader.setUniform("texelSize", TEXEL_SIZE)
		RDShader.setUniform("mouse", [p.mouseX / WIDTH, p.mouseY / HEIGHT])
		RDShader.setUniform("FEED", PARAMS.Feed)
		RDShader.setUniform("KILL", PARAMS.Kill)
		RDShader.setUniform("DeltaT", PARAMS.DeltaT)
		RDShader.setUniform("Scale", PARAMS.Scale)
		RDShader.setUniform("Radius", PARAMS.Radius)
		RDShader.setUniform("Wrap", PARAMS.Wrap)
		RDShader.setUniform("Cursor", p.mouseIsPressed && !onDrage())
		RDShader.setUniform("Clear", PARAMS.Clear)
		PARAMS.Clear && (PARAMS.Clear = false)
		p.quad(-1, 1, 1, 1, 1, -1, -1, -1)
		next.end()

	}
}
const render = () => {
	p.shader(RenderShader)
	RenderShader.setUniform("tex0", next)
	RenderShader.setUniform("canvasSize", CANVAS_SIZE)
	RenderShader.setUniform("texelSize", TEXEL_SIZE)
	RenderShader.setUniform("Wrap", PARAMS.Wrap)
	RenderShader.setUniform("Brightness", xyz(PARAMS.Render.Palette.Brightness))
	RenderShader.setUniform("Constrast", xyz(PARAMS.Render.Palette.Constrast))
	RenderShader.setUniform("Oscilates", xyz(PARAMS.Render.Palette.Oscilates))
	RenderShader.setUniform("Phase", xyz(PARAMS.Render.Palette.Phase))
	RenderShader.setUniform("Emboss", PARAMS.Render.Emboss)
	RenderShader.setUniform("Offset", PARAMS.Render.Offset)
	p.quad(-1, 1, 1, 1, 1, -1, -1, -1)
}
const xyz = (obj) => [obj.x, obj.y, obj.z]

	const extractBlackPixels = () => {
	console.log("Début extraction")

	let canvas = document.querySelector('canvas')
	let gl = canvas.getContext('webgl2') || canvas.getContext('webgl')

	let canvasWidth = p.width
	let canvasHeight = p.height

	let pixels = new Uint8Array(canvasWidth * canvasHeight * 4)
	gl.readPixels(0, 0, canvasWidth, canvasHeight, gl.RGBA, gl.UNSIGNED_BYTE, pixels)

	console.log(`Dimensions: ${canvasWidth}x${canvasHeight}`)
	console.log(`seuil = ${PARAMS.Seuil}`)
	console.log(`précision = ${PARAMS.Precision}`)

	let step = PARAMS.Precision || 1
	var scale = 1 / step // Facteur d'échelle (0.5 -> scale 2, 0.25 -> scale 4)

	for (let y = 0; y < canvasHeight; y += step) {
		for (let x = 0; x < canvasWidth; x += step) {
			let px = Math.floor(x)
			let py = Math.floor(y)

			if (px >= canvasWidth || py >= canvasHeight) continue

			let index = (py * canvasWidth + px) * 4
			let r = pixels[index]
			let g = pixels[index + 1]
			let b = pixels[index + 2]

			let brightness = (r + g + b) / 3
			if (brightness < PARAMS.Seuil) {
				// Appliquer le scale
				let xWebGL = (x - canvasWidth / 2) * scale
				let yWebGL = -(y - canvasHeight / 2) * scale

				blackPixels.push({ x: xWebGL, y: yWebGL })
			}
		}
	}

	console.log(`${blackPixels.length} pixels noirs trouvés`)
}

})


